        "Osnovna ideja: der Besuch je imenica muškog roda s dva glavna značenja: poseta (posećivanje nekog mesta, Besuch im Museum) i gosti ili gostovanje (Wir haben Besuch).",
        "Množina je die Besuche. Goste obično označava jednina bez člana: Wir bekommen Besuch (dolaze nam gosti); gostovanje: zu Besuch sein (biti u gostima).",
