      "explanation": [
        "Glavna ideja: können (moći, umeti) je modalni glagol. Izražava sposobnost (Er kann schwimmen — on ume da pliva), mogućnost (Wir können heute kommen — možemo da dođemo danas) i molbu (Kannst du mir helfen? — Možeš li da mi pomogneš?).",
        "Oblici: ich kann, du kannst, er/sie/es kann, wir können, ihr könnt, sie können; preterit konnte, perfekat hat gekonnt. Drugi glagol stoji u infinitivu na kraju rečenice: Ich kann heute nicht kommen.",
        "Kad se govori o jezicima i veštinama, können može da stoji i bez drugog glagola: Ich kann Deutsch (znam nemački)."
      ],
      "examples": [
        {
          "de": "Ich kann Deutsch sprechen.",
          "lv": "Znam da govorim nemački."
        },
        {
          "de": "Kannst du mir helfen?",
          "lv": "Možeš li da mi pomogneš?"
        },
        {
          "de": "Wir können heute kommen.",
          "lv": "Danas možemo da dođemo."
        },
        {
          "de": "Er kann gut schwimmen.",
          "lv": "On ume dobro da pliva."
        },
        {
          "de": "Sie kann leider nicht kommen.",
          "lv": "Nažalost, ona ne može da dođe."
        }
      ],
      "comparison": [
        {
          "word": "dürfen",
          "meaning": "smeti",
          "example": "Hier darf man nicht rauchen. – Ovde se ne sme pušiti."
        },
        {
          "word": "müssen",
          "meaning": "morati, trebati",
          "example": "Ich muss arbeiten. – Moram da radim."
        },
        {
          "word": "kennen",
          "meaning": "poznavati",
          "example": "Ich kenne ihn. – Poznajem ga."
        }
      ],
      "tip": [
        "Ich kann, er kann — u 1. i 3. licu jednine nema nastavka: ich kann, er kann.",
        "Znati nešto (jezik, igru) može se reći i bez glagola: Kannst du Schach? — Znaš li šah?"
      ],
      "important": [
        "Können i kennen ne mešaj: können — moći/umeti, kennen — poznavati.",
        "U perfektu modalnog glagola obično se koristi zamenski oblik: Ich habe nicht kommen können (infinitiv na kraju)."
      ],
