      "translation": "oni • one • ona",
      "explanation": [
        "Glavna ideja: sie je zamenica 3. lica. U jednini znači ona (sie ist), u množini — oni ili one (sie sind). Nastavak glagola pokazuje šta je od toga mišljeno: sie kommt (ona) i sie kommen (oni).",
        "Padeži: akuzativ sie (ich sehe sie), dativ u jednini ihr, u množini ihnen. Kada se govori o stvari sa članom ženskog roda, i ona se može zameniti sa sie: die Tasche – sie.",
        "Sie velikim slovom (Sie) je učtivo „Vi“; na početku rečenice razliku pomažu da se uoče sadržaj i oblik glagola."
      ],
      "examples": [
        {
          "de": "Sie ist meine Lehrerin.",
          "lv": "Ona je moja učiteljica."
        },
        {
          "de": "Sie wohnen in Riga.",
          "lv": "Oni žive u Rigi."
        },
        {
          "de": "Ich sehe sie jeden Tag.",
          "lv": "Viđam je svaki dan."
        },
        {
          "de": "Sie sind noch zu Hause.",
          "lv": "Oni su još kod kuće."
        },
        {
          "de": "Ich gebe ihr das Buch.",
          "lv": "Dajem joj knjigu."
        }
      ],
